package io.mateu.ijp.update

import com.fasterxml.jackson.databind.JsonNode
import com.fasterxml.jackson.databind.ObjectMapper

/**
 * The desktop app's update FEED (`mateu-desktop-update.json`, attached to every GitHub release by
 * `.github/workflows/desktop.yml` and generated by the `desktopUpdateFeed` Gradle task):
 *
 *   {
 *     "version": "3.0-beta.27",
 *     "plugin": { "url": "https://…/mateu-intellij-plugin-3.0-beta.27.zip", "sha256": "…" },
 *     "platform": {
 *       "ideVersion": "2025.2.6.3",
 *       "installers": { "macos-aarch64": "…", "macos-intel": "…", "linux": "…", "windows": "…" }
 *     },
 *     "notes": "…"
 *   }
 *
 * The plugin is what the app updates by itself (download, verify, stage, swap at the next launch);
 * the platform (the IntelliJ build under it) is never patched — a different `ideVersion` asks the
 * user to reinstall from the installer for their OS.
 */
data class UpdateFeed(
    val version: String,
    val plugin: PluginRelease?,
    val ideVersion: String?,
    val installers: Map<String, String>,
    val notes: String?,
) {
    data class PluginRelease(val url: String, val sha256: String)

    companion object {
        /** The feed of the latest Mateu release (GitHub's `latest` = the newest non-prerelease). */
        const val DEFAULT_URL =
            "https://github.com/miguelperezcolom/mateu/releases/latest/download/mateu-desktop-update.json"

        private val SHA256 = Regex("^[0-9a-fA-F]{64}$")

        /** Parses a feed; a document without a version is not a feed. A plugin entry with a non-https
         *  url or a malformed digest is dropped (the app then never downloads it), not trusted. */
        fun parse(json: String, mapper: ObjectMapper = ObjectMapper()): UpdateFeed {
            val node = mapper.readTree(json) ?: throw IllegalArgumentException("empty update feed")
            val version = node.path("version").text()
                ?: throw IllegalArgumentException("the update feed has no version")
            val pluginNode = node.path("plugin")
            val pluginUrl = pluginNode.path("url").text()
            val sha = pluginNode.path("sha256").text()
            val plugin = if (pluginUrl != null && sha != null && isAllowedUrl(pluginUrl) && SHA256.matches(sha)) {
                PluginRelease(pluginUrl, sha.lowercase())
            } else {
                null
            }
            val platform = node.path("platform")
            val installers = buildMap {
                platform.path("installers").fields().forEach { (key, value) ->
                    value.text()?.takeIf(::isAllowedUrl)?.let { put(key, it) }
                }
            }
            return UpdateFeed(version, plugin, platform.path("ideVersion").text(), installers, node.path("notes").text())
        }

        /** https only — a feed or a download over plain http could be swapped on the way. Loopback is
         *  the exception, for a local feed while testing. */
        fun isAllowedUrl(url: String): Boolean {
            val lower = url.trim().lowercase()
            return lower.startsWith("https://") ||
                lower.startsWith("http://localhost:") || lower.startsWith("http://localhost/") ||
                lower.startsWith("http://127.0.0.1:") || lower.startsWith("http://127.0.0.1/")
        }

        private fun JsonNode.text(): String? =
            if (isMissingNode || isNull || !isValueNode) null else asText().trim().ifBlank { null }
    }
}

/** Which installer of the feed fits this machine: `macos-aarch64`, `macos-intel`, `linux`, `windows`.
 *  The desktop build bakes it (`-Dmateu.desktop.platform`); this is the fallback from the JVM's own
 *  os.name/os.arch. */
fun installerKey(osName: String, osArch: String): String {
    val os = osName.lowercase()
    return when {
        os.contains("mac") || os.contains("darwin") ->
            if (osArch.lowercase().let { it == "aarch64" || it == "arm64" }) "macos-aarch64" else "macos-intel"
        os.contains("win") -> "windows"
        else -> "linux"
    }
}

/**
 * Orders Mateu versions: numbers numerically, then alpha < beta < rc < GA —
 * `3.0-alpha.412 < 3.0-beta.9 < 3.0-beta.26 < 3.0-rc.1 < 3.0 == 3.0.0 < 3.0.1`. An unknown
 * qualifier (`-SNAPSHOT`, a dev build) sorts below alpha, so a released build always wins over it.
 * [io.mateu.ijp.plugin.AppRegistry.compareVersions] stays numeric-only on purpose (registry gates).
 */
fun compareDesktopVersions(a: String, b: String): Int {
    val va = DesktopVersion.of(a)
    val vb = DesktopVersion.of(b)
    for (i in 0 until maxOf(va.numbers.size, vb.numbers.size)) {
        val c = (va.numbers.getOrNull(i) ?: 0L).compareTo(vb.numbers.getOrNull(i) ?: 0L)
        if (c != 0) return c
    }
    if (va.stage != vb.stage) return va.stage.compareTo(vb.stage)
    for (i in 0 until maxOf(va.stageNumbers.size, vb.stageNumbers.size)) {
        val c = (va.stageNumbers.getOrNull(i) ?: 0L).compareTo(vb.stageNumbers.getOrNull(i) ?: 0L)
        if (c != 0) return c
    }
    return 0
}

private class DesktopVersion(val numbers: List<Long>, val stage: Int, val stageNumbers: List<Long>) {
    companion object {
        private const val UNKNOWN = -1
        private const val GA = 3
        private val STAGES = mapOf("alpha" to 0, "a" to 0, "beta" to 1, "b" to 1, "rc" to 2, "cr" to 2)

        fun of(raw: String): DesktopVersion {
            val v = raw.trim().removePrefix("v")
            val dash = v.indexOf('-')
            val main = if (dash < 0) v else v.substring(0, dash)
            val qualifier = if (dash < 0) "" else v.substring(dash + 1)
            val numbers = main.split('.').map { part -> part.takeWhile(Char::isDigit).toLongOrNull() ?: 0L }
            if (qualifier.isEmpty()) return DesktopVersion(numbers, GA, emptyList())
            val parts = qualifier.split('.', '-')
            val name = parts.first().takeWhile(Char::isLetter).lowercase()
            val stage = STAGES[name] ?: UNKNOWN
            // "beta.26" and "beta26" both carry 26
            val inline = parts.first().dropWhile(Char::isLetter).toLongOrNull()
            val rest = parts.drop(1).mapNotNull { it.takeWhile(Char::isDigit).toLongOrNull() }
            return DesktopVersion(numbers, stage, listOfNotNull(inline) + rest)
        }
    }
}
